    {
      "keystrokes": "curl -s -X POST http://colormind.io/api/ -H 'Content-Type: application/json' -d '{\"model\":\"ui\",\"locked\":[\"18,18,30\",\"92,88,184\",\"34,193,195\",\"N\",\"N\"]}'\n",
      "duration": 5.0
